// ─────────────────────────────────────────────────────────────────────────────
// Persona classification — a rule table, deliberately not an LLM
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Personas drive who gets emailed first, so this has to be auditable: when the
 * operator asks why a VP Eng was ranked above the Head of Talent, the answer
 * must be a line of this table, not a sampled token. It is also free and runs
 * in microseconds over thousands of rows.
 *
 * Order matters. The first match wins, so specific titles are listed before the
 * generic seniority fallback.
 */
const PERSONA_RULES: { persona: Persona; re: RegExp }[] = [
  {
    persona: 'founder_ceo',
    re: /\b(co[-\s]?founder|founder|founding (partner|team)|c\.?e\.?o\.?|chief executive|managing director|owner|proprietor)\b/i,
  },
  {
    persona: 'cto_vpe',
    re: /\b(c\.?t\.?o\.?|chief technolog\w*|chief technical|chief architect|v\.?p\.?\s*(of\s*)?(engineering|eng|technology|r&d)|vice president[,\s]+(of\s+)?(engineering|technology)|svp\s*(of\s*)?engineering|head of (engineering|technology|platform|infrastructure)|director of engineering|engineering director|vp eng)\b/i,
  },
  {
    persona: 'head_of_talent',
    re: /\b(head of (talent|people|recruiting|recruitment|hr|human resources)|chief people|chief talent|c\.?h\.?r\.?o\.?|v\.?p\.?\s*(of\s*)?(talent|people|hr|human resources)|vice president[,\s]+(of\s+)?(talent|people)|director of (talent|people|recruiting|recruitment|hr|human resources)|talent director|people director|head of talent acquisition)\b/i,
  },
  {
    persona: 'recruiter',
    re: /\b(recruiter|recruiting (manager|lead|partner|coordinator|specialist)|technical recruiting|talent acquisition|talent partner|talent manager|talent lead|sourcer|sourcing (lead|specialist|manager)|people ops|people operations|hr (manager|generalist|business partner|coordinator)|hrbp|staffing)\b/i,
  },
  {
    persona: 'coo_ops',
    re: /\b(c\.?o\.?o\.?|chief operating|chief of staff|c\.?f\.?o\.?|chief financial|v\.?p\.?\s*(of\s*)?(operations|ops|finance)|head of (operations|ops|finance|business operations)|director of operations|business operations|controller|office manager)\b/i,
  },
  {
    persona: 'hiring_manager',
    re: /\b(head of|director|senior director|v\.?p\.?|vice president|manager|team lead|tech lead|lead engineer|principal|staff engineer|chief \w+ officer|c\.?p\.?o\.?|c\.?m\.?o\.?|c\.?r\.?o\.?)\b/i,
  },
];

export function classifyPersona(title: string | null | undefined): Persona | null {
  if (!title) return null;
  const t = title.replace(/\s+/g, ' ').trim();
  if (!t) return null;
  for (const { persona, re } of PERSONA_RULES) {
    if (re.test(t)) return persona;
  }
  return 'other';
}

const SENIORITY_RULES: { level: string; re: RegExp }[] = [
  { level: 'founder', re: /\b(co[-\s]?founder|founder)\b/i },
  { level: 'c_level', re: /\b(c\.?[a-z]\.?o\.?|chief\s+\w+)\b/i },
  { level: 'vp', re: /\b(v\.?p\.?|vice president|svp|evp)\b/i },
  { level: 'director', re: /\b(director|head of)\b/i },
  { level: 'manager', re: /\b(manager|lead)\b/i },
  { level: 'ic', re: /\b(engineer|designer|analyst|specialist|coordinator|associate|recruiter|sourcer)\b/i },
];

export function classifySeniority(title: string | null | undefined): string | null {
  if (!title) return null;
  for (const { level, re } of SENIORITY_RULES) if (re.test(title)) return level;
  return null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Provenance
// ─────────────────────────────────────────────────────────────────────────────

export interface ObservationInput {
  entity: 'company' | 'contact' | 'req';
  entityId: string;
  field: string;
  value: string | null;
  source: SourceId;
  evidenceId: number | null;
  confidence: Confidence;
}

/**
 * Append the observation, then recompute the winner for that field. Resolving
 * at write time is what lets the UI read a field with one b-tree seek instead
 * of a window function over the whole history.
 */
export function recordObservation(db: Db, o: ObservationInput): number {
  const inserted = prep(
    db,
    `INSERT INTO field_observation (entity, entity_id, field, value, source, evidence_id, confidence)
     VALUES (?, ?, ?, ?, ?, ?, ?)
     RETURNING id`,
  ).get(o.entity, o.entityId, o.field, o.value, o.source, o.evidenceId, o.confidence) as { id: number };

  // ONE resolver for the whole app — ingest.ts's, which ranks by source trust
  // (an inference can never beat something actually observed) and computes
  // conflict over the latest observation per source. This module used to run
  // its own confidence-ranked variant with all-history conflicts; whichever
  // wrote last won, and the provenance panel depended on write order.
  resolveEntityField(db, o.entity, o.entityId, o.field);
  return inserted.id;
}

