export function loadCompany(db: Db, companyId: string): Company | null {
  const r = get<CompanyDbRow>(db, 'SELECT * FROM company WHERE id = ?', companyId);
  if (!r) return null;
  return {
    id: r.id,
    domain: r.domain,
    name: r.name,
    nameNorm: r.name_norm,
    headcount: r.headcount,
    headcountSource: null,
    industry: r.industry,
    hqLocation: r.hq_location,
    inBayArea: r.in_bay_area === 1,
    fundingStage: r.funding_stage,
    lastRoundAt: r.last_round_at == null ? null : new Date(r.last_round_at).toISOString(),
    atsPlatform: (r.ats_platform as Company['atsPlatform']) ?? null,
    atsToken: r.ats_token,
    careersUrl: r.careers_url,
    linkedinUrl: r.linkedin_url,
    ycBatch: r.yc_batch,
    openReqCount: r.open_req_count,
    openReqEngCount: r.open_req_eng_count,
    maxDaysOpen: r.max_days_open,
    staleReqCount: r.stale_req_count,
    recruiterCount: r.recruiter_count,
    hasInhouseTa: r.has_inhouse_ta == null ? null : r.has_inhouse_ta === 1,
    noAgencyPolicy: r.no_agency_policy === 1,
    qualityScore: r.quality_score,
    scoreBreakdown: r.score_breakdown,
    status: r.status as Company['status'],
    reviewed: r.reviewed === 1,
    reviewedAt: r.reviewed_at == null ? null : new Date(r.reviewed_at).toISOString(),
    notes: r.notes,
    createdAt: new Date(r.created_at).toISOString(),
    updatedAt: new Date(r.updated_at).toISOString(),
  };
}

